<!doctype html><html lang="en"><head><meta charset="utf-8"><title>{{ $transmittal->ref_no }} · Printable</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{font:12px Arial,sans-serif;color:#17202a;margin:0}.toolbar{display:flex;justify-content:flex-end;margin-bottom:15px}.toolbar button{padding:8px 14px;background:#111827;color:white;border:0;border-radius:5px;cursor:pointer}.head{border-bottom:3px solid #f27933;padding-bottom:12px;display:flex;justify-content:space-between;align-items:flex-end}.brand{font-weight:bold;font-size:20px;letter-spacing:.08em}.brand small{display:block;font-size:8px;letter-spacing:.16em;color:#617081;margin-top:3px}.title{text-align:right;font-weight:bold;font-size:18px;letter-spacing:.09em}.meta{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid #bbc5cf;margin-top:20px}.meta div{padding:10px;border-right:1px solid #bbc5cf;min-height:50px}.meta div:nth-child(3n){border-right:0}.meta label,.note label{display:block;color:#687583;text-transform:uppercase;font-size:8px;letter-spacing:.09em;margin-bottom:5px}.meta strong{font-size:12px}.table{width:100%;border-collapse:collapse;margin-top:20px}.table th{background:#17202a;color:#fff;text-align:left;text-transform:uppercase;font-size:9px;letter-spacing:.06em}.table td,.table th{border:1px solid #bbc5cf;padding:9px}.note{border:1px solid #bbc5cf;padding:10px;margin-top:18px;min-height:55px}.signatures{display:grid;grid-template-columns:repeat(3,1fr);gap:25px;margin-top:52px}.sig{border-top:1px solid #17202a;padding-top:7px}.sig small{color:#687583}@media print{.toolbar{display:none}}</style></head><body><div class="toolbar"><button onclick="window.print()">Print</button></div><div class="head"><div class="brand">PMC<small>TRANSMITTAL DESK</small></div><div class="title">{{ strtoupper($transmittal->transmittal_type) }} TRANSMITTAL</div></div><div class="meta"><div><label>Reference no.</label><strong>{{ $transmittal->ref_no }}</strong></div><div><label>Date</label><strong>{{ $transmittal->transmittal_date->format('d M Y') }}</strong></div><div><label>Status</label><strong>{{ $transmittal->status }}</strong></div><div><label>Destination / source</label><strong>{{ $transmittal->destination }}</strong></div><div><label>Plate no.</label><strong>{{ $transmittal->plate_no ?: '—' }}</strong></div><div><label>Attachment</label><strong>{{ $transmittal->attachment ? 'Attached' : 'None' }}</strong></div></div><table class="table"><thead><tr><th style="width:7%">#</th><th>Description</th><th style="width:12%">Unit</th><th style="width:20%">Serial no.</th><th style="width:20%">Remarks</th></tr></thead><tbody>@foreach($transmittal->details as $i=>$detail)<tr><td>{{ $i+1 }}</td><td>{{ $detail->item_desc }}</td><td>{{ $detail->item_unit ?: '—' }}</td><td>{{ $detail->item_serial_no ?: '—' }}</td><td>{{ $detail->remarks ?: '—' }}</td></tr>@endforeach</tbody></table><div class="note"><label>Remarks</label>{{ $transmittal->remarks ?: '—' }}</div><div class="signatures"><div class="sig"><strong>{{ $transmittal->prepared_by }}</strong><br><small>Prepared by</small></div><div class="sig"><strong>{{ $transmittal->received_by ?: ' ' }}</strong><br><small>Received by</small></div><div class="sig"><strong>{{ $transmittal->noted_by ?: ' ' }}</strong><br><small>Noted by</small></div></div></body></html>
